<script>
	import { onMount } from 'svelte';
	let events = $state(/** @type {any[]} */ ([])); let error = $state(''); let verified = $state(/** @type {any} */ (null)); let action = $state('');
	async function load() { const query = action ? `?action=${encodeURIComponent(action)}` : ''; const response = await fetch(`/manager/api/audit${query}`); if (!response.ok) throw new Error('Audit log unavailable'); events = (await response.json()).events ?? []; }
	async function verify() { const response = await fetch('/manager/api/audit/verify'); verified = await response.json(); }
	onMount(async () => { try { await load(); } catch (cause) { error = cause instanceof Error ? cause.message : 'Audit log unavailable'; } });
</script>
<svelte:head><title>Audit · RunWisp Manager</title></svelte:head>
<section class="audit-page"><p class="kicker">Accountability trail</p><h1>Audit.</h1><div class="toolbar"><input aria-label="Filter action" bind:value={action} placeholder="action, e.g. config.save" /><button onclick={load}>Filter</button><button onclick={verify}>Verify chain</button><a href="/manager/api/audit/export?format=ndjson">Export NDJSON</a></div>{#if error}<p class="error">{error}</p>{/if}{#if verified}<p class:bad={!verified.valid} class="verification">{verified.valid ? 'Chain verified.' : `Chain broken at ${verified.firstBrokenID}.`}</p>{/if}<div class="table" role="table"><div class="row heading"><span>When</span><span>Actor</span><span>Action</span><span>Outcome</span></div>{#each events as event}<div class="row"><time datetime={event.ts}>{new Date(event.ts).toLocaleString()}</time><span>{event.username || 'system'}</span><code>{event.action}</code><span class:denied={event.outcome !== 'ok'}>{event.outcome}</span></div>{:else}<p>No audit events.</p>{/each}</div></section>
<style>.audit-page{max-width:1000px;padding:7vh 2vw}.kicker{font:11px ui-monospace,monospace;opacity:.55}h1{font-size:clamp(34px,5vw,58px);letter-spacing:-.06em;margin:0 0 28px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}.toolbar input,.toolbar button,.toolbar a{border:1px solid var(--color-border,#d8dee8);background:transparent;color:inherit;padding:9px 12px;font:inherit;font-size:12px;text-decoration:none}.table{border-top:1px solid var(--color-border,#d8dee8)}.row{display:grid;grid-template-columns:1.4fr 1fr 1.6fr .7fr;gap:12px;padding:12px 4px;border-bottom:1px solid var(--color-border,#d8dee8);font-size:12px}.heading{opacity:.55;font-size:10px}.denied,.bad,.error{color:#a45b2a}.verification{font-size:12px;margin:14px 0}@media(max-width:700px){.row{grid-template-columns:1fr 1fr}.row span:nth-child(3){grid-column:1/-1}}</style>
